import{_ as a,o as i,c as e,a2 as n}from"./chunks/framework.BiXHgXAn.js";const c=JSON.parse('{"title":"FAQ","description":"Frequently asked questions about Task, including ETAs, shell limitations, and Windows compatibility","frontmatter":{"title":"FAQ","description":"Frequently asked questions about Task, including ETAs, shell limitations, and Windows compatibility","section":"Project","docType":"project","outline":"deep"},"headers":[],"relativePath":"docs/faq.md","filePath":"next/docs/faq.md"}'),t={name:"docs/faq.md"};function l(o,s,h,p,r,d){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>This page contains a list of frequently asked questions about Task.</p><h2 id="when-will-feature-be-released-etas" tabindex="-1">When will &lt;feature&gt; be released? / ETAs <a class="header-anchor" href="#when-will-feature-be-released-etas" aria-label="Permalink to &quot;When will \\&lt;feature\\&gt; be released? / ETAs&quot;">​</a></h2><p>Task is <em>free</em> and <em>open source</em> project maintained by a small group of volunteers with full time jobs and lives outside of the project. Because of this, it is difficult to predict how much time we will be able to dedicate to the project in advance and we don&#39;t want to make any promises that we can&#39;t keep. For this reason, we are unable to provide ETAs for new features or releases. We make a &quot;best effort&quot; to provide regular releases and fix bugs in a timely fashion, but sometimes our personal lives must take priority.</p><p>ETAs are probably the number one question we (and maintainers of other open source projects) get asked. We understand that you are passionate about the project, but it can be overwhelming to be asked this question so often. Please be patient and avoid asking for ETAs.</p><p>The best way to speed things up is to contribute to the project yourself. We always appreciate new contributors. If you are interested in contributing, check out the <a href="./contributing">contributing guide</a>.</p><h2 id="why-won-t-my-task-update-my-shell-environment" tabindex="-1">Why won&#39;t my task update my shell environment? <a class="header-anchor" href="#why-won-t-my-task-update-my-shell-environment" aria-label="Permalink to &quot;Why won&#39;t my task update my shell environment?&quot;">​</a></h2><p>This is a limitation of how shells work. Task runs as a subprocess of your current shell, so it can&#39;t change the environment of the shell that started it. This limitation is shared by other task runners and build tools too.</p><p>A common way to work around this is to create a task that will generate output that can be parsed by your shell. For example, to set an environment variable on your shell you can write a task like this:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">my-shell-env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  cmds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">echo &quot;export FOO=foo&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">echo &quot;export BAR=bar&quot;</span></span></code></pre></div><p>Now run <code>eval $(task my-shell-env)</code> and the variables <code>$FOO</code> and <code>$BAR</code> will be available in your shell.</p><h2 id="i-can-t-reuse-my-shell-in-a-task-s-commands" tabindex="-1">I can&#39;t reuse my shell in a task&#39;s commands <a class="header-anchor" href="#i-can-t-reuse-my-shell-in-a-task-s-commands" aria-label="Permalink to &quot;I can&#39;t reuse my shell in a task&#39;s commands&quot;">​</a></h2><p>Task runs each command as a separate shell process, so something you do in one command won&#39;t effect any future commands. For example, this won&#39;t work:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;3&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tasks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  foo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cmds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">a=foo</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">echo $a</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # outputs &quot;&quot;</span></span></code></pre></div><p>To work around this you can either use a multiline command:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;3&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tasks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  foo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cmds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        a=foo</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        echo $a</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # outputs &quot;foo&quot;</span></span></code></pre></div><p>Or for more complex multi-line commands it is recommended to move your code into a separate file and call that instead:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;3&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tasks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  foo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cmds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">./foo-printer.bash</span></span></code></pre></div><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#!/bin/bash</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">a</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">foo</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $a</span></span></code></pre></div><h2 id="are-shell-core-utilities-available-on-windows" tabindex="-1">Are shell core utilities available on Windows? <a class="header-anchor" href="#are-shell-core-utilities-available-on-windows" aria-label="Permalink to &quot;Are shell core utilities available on Windows?&quot;">​</a></h2><p>The most common ones, yes. And we might add more in the future. This is possible because Task compiles a small set of core utilities in Go and enables them by default on Windows for greater compatibility.</p><p>It&#39;s possible to control whether these builtin core utilities are used or not with the <a href="./reference/environment#task-core-utils"><code>TASK_CORE_UTILS</code></a> environment variable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Enable, even on non-Windows platforms</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TASK_CORE_UTILS=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Disable, even on Windows</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TASK_CORE_UTILS=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span></span></code></pre></div><p>This is the list of core utils that are currently available:</p><ul><li><code>base64</code></li><li><code>cat</code></li><li><code>chmod</code></li><li><code>cp</code></li><li><code>find</code></li><li><code>gzip</code></li><li><code>ls</code></li><li><code>mkdir</code></li><li><code>mktemp</code></li><li><code>mv</code></li><li><code>rm</code></li><li><code>shasum</code></li><li><code>tar</code></li><li><code>touch</code></li><li><code>xargs</code></li><li>(more might be added in the future)</li></ul>`,25)])])}const u=a(t,[["render",l]]);export{c as __pageData,u as default};
